```
 /*Hides the lightbox header and footer to make the image area larger. Mouse reveals them as an overlay to the image*/

.Lightbox-header,
.Lightbox-footer{
z-index:9999;
 position:absolute;
 width:100%;
 opacity:0;
background-color:#0008;
 transition: opacity 0.5s ease;
}

.Lightbox-footer{
bottom:0;}

